import enum

from harness import EnvironmentSetupError, run_agent, grade, load_tasks


class Outcome(str, enum.Enum):
    PASS = "pass"
    FAIL = "fail"
    HARNESS_ERROR = "harness_error"


def score_task(task):
    try:
        trace = run_agent(task)
    except EnvironmentSetupError:
        return Outcome.HARNESS_ERROR
    except Exception:
        return Outcome.FAIL
    return Outcome.PASS if grade(task, trace) else Outcome.FAIL


def score_all():
    outcomes = [score_task(t) for t in load_tasks()]
    attempted = [o for o in outcomes if o is not Outcome.HARNESS_ERROR]
    broken = len(outcomes) - len(attempted)
    passed = sum(1 for o in attempted if o is Outcome.PASS)
    return {"accuracy": passed / max(len(attempted), 1),
            "attempted": len(attempted), "harness_error": broken}
